//! Compare lutmatrix-core colour math against colour-science reference values
//! (`tests/fixtures/reference.json`, generated by `tools/gen_fixtures.py`).

use lutmatrix_core::math::{whites, Cat, Mat3, Primaries, Vec3};
use lutmatrix_core::spaces::curves::ARRI_LOGC3_EIS;
use lutmatrix_core::spaces::display::{pq_eotf, pq_inverse_eotf};
use lutmatrix_core::spaces::{davinci, gamuts, LogCurve};
use serde_json::Value;

fn fixtures() -> Value {
    let s = include_str!("fixtures/reference.json");
    serde_json::from_str(s).unwrap()
}

fn mat(v: &Value) -> Mat3 {
    let r: Vec<Vec<f64>> = serde_json::from_value(v.clone()).unwrap();
    Mat3::new(
        r[0][0], r[0][1], r[0][2], r[1][0], r[1][1], r[1][2], r[2][0], r[2][1], r[2][2],
    )
}

fn curve_for(key: &str) -> LogCurve {
    if let Some(ei) = key.strip_prefix("arri_logc3_ei") {
        return LogCurve::ArriLogC3 { ei: ei.parse().unwrap() };
    }
    match key {
        "arri_logc4" => LogCurve::ArriLogC4,
        "slog3" => LogCurve::SLog3,
        "log3g10" => LogCurve::Log3G10,
        "canon_log2" => LogCurve::CanonLog2,
        "canon_log3" => LogCurve::CanonLog3,
        "vlog" => LogCurve::VLog,
        "bmd_film_gen5" => LogCurve::BmdFilmGen5,
        "flog" => LogCurve::FLog,
        "flog2" => LogCurve::FLog2,
        "davinci_intermediate" => LogCurve::DaVinciIntermediate,
        "acescct" => LogCurve::AcesCct,
        other => panic!("fixture has unknown curve {other}"),
    }
}

fn gamut_for(key: &str) -> Primaries {
    match key {
        "awg3" => gamuts::AWG3,
        "awg4" => gamuts::AWG4,
        "s_gamut3" => gamuts::S_GAMUT3,
        "s_gamut3_cine" => gamuts::S_GAMUT3_CINE,
        "rwg" => gamuts::RWG,
        "cinema_gamut" => gamuts::CINEMA_GAMUT,
        "v_gamut" => gamuts::V_GAMUT,
        "bmd_wg_gen5" => gamuts::BMD_WG_GEN5,
        "f_gamut" => gamuts::F_GAMUT,
        "dwg" => gamuts::DWG,
        "ap1" => gamuts::AP1,
        "ap0" => gamuts::AP0,
        "rec709" => gamuts::REC709,
        "p3_d65" => gamuts::P3_D65,
        "p3_dci" => gamuts::P3_DCI,
        "rec2020" => gamuts::REC2020,
        other => panic!("fixture has unknown gamut {other}"),
    }
}

/// Known gaps in manufacturer-published constants, allowed only right at the
/// linear/log breakpoint (the published constants are kept exactly as printed):
/// - V-Log: decode cut2 = 0.181 is a rounding of encode(cut1) = 0.18099969.
/// - F-Log / F-Log2: decode cut2 does not equal encode(cut1), leaving a ~1e-5 linear
///   overlap in deep shadow (Fujifilm data sheets Ver.1.1 / Ver.1.0).
fn breakpoint_slack(c: LogCurve, x: f64) -> f64 {
    let (cut, slack) = match c {
        LogCurve::VLog => (0.01, 1e-7),
        LogCurve::FLog => (0.00089, 2e-5),
        LogCurve::FLog2 => (0.000889, 2e-5),
        _ => return 0.0,
    };
    if (x - cut).abs() < 0.0005 { slack } else { 0.0 }
}

#[test]
fn every_curve_matches_colour_science() {
    let f = fixtures();
    let curves = f["curves"].as_object().unwrap();
    // Every LogC3 EI and every non-ARRI curve must be covered by the fixture.
    assert_eq!(curves.len(), 11 + ARRI_LOGC3_EIS.len());
    for (key, rows) in curves {
        let c = curve_for(key);
        for row in rows.as_array().unwrap() {
            let x = row[0].as_f64().unwrap();
            let want = row[1].as_f64().unwrap();
            let got = c.encode(x);
            assert!(
                (got - want).abs() < 1e-9,
                "{key}: encode({x}) = {got}, colour-science = {want}"
            );
            let back = c.decode(want);
            assert!(
                (back - x).abs() <= 1e-9 * x.abs().max(1.0) + breakpoint_slack(c, x),
                "{key}: decode({want}) = {back}, expected {x}"
            );
        }
    }
}

#[test]
fn curve_round_trip_dense() {
    let mut curves: Vec<LogCurve> = ARRI_LOGC3_EIS.iter().map(|&ei| LogCurve::ArriLogC3 { ei }).collect();
    curves.extend([
        LogCurve::ArriLogC4,
        LogCurve::SLog3,
        LogCurve::Log3G10,
        LogCurve::CanonLog2,
        LogCurve::CanonLog3,
        LogCurve::VLog,
        LogCurve::BmdFilmGen5,
        LogCurve::FLog,
        LogCurve::FLog2,
        LogCurve::DaVinciIntermediate,
        LogCurve::AcesCct,
        LogCurve::Linear,
    ]);
    for c in curves {
        // linear → code → linear across -0.01 … 64 (log-spaced above 0)
        for i in 0..=400 {
            let x = if i < 20 { -0.01 + i as f64 * 0.0005 } else { 2f64.powf(-12.0 + (i - 20) as f64 * 18.0 / 380.0) };
            let y = c.decode(c.encode(x));
            assert!(
                (y - x).abs() <= 1e-10 * x.abs().max(1.0) + breakpoint_slack(c, x),
                "{}: {x} → {y}",
                c.name()
            );
        }
        // code → linear → code across the full code range
        for i in 0..=200 {
            let v = i as f64 / 200.0;
            let w = c.encode(c.decode(v));
            let slack = breakpoint_slack(c, c.decode(v)) * 10.0;
            assert!((w - v).abs() < 1e-10 + slack, "{}: code {v} → {w}", c.name());
        }
        // monotonic
        let mut prev = f64::NEG_INFINITY;
        for i in 0..=1000 {
            let v = c.encode(-0.01 + i as f64 * 0.02);
            assert!(v > prev, "{} not monotonic", c.name());
            prev = v;
        }
    }
}

#[test]
fn npm_matches_colour_science_derived() {
    let f = fixtures();
    for (key, m) in f["npm"].as_object().unwrap() {
        let ours = gamut_for(key).rgb_to_xyz();
        let theirs = mat(m);
        let d = (ours - theirs).abs().max();
        assert!(d < 1e-12, "{key}: NPM differs from colour-science by {d}");
    }
}

#[test]
fn npm_close_to_manufacturer_published() {
    // Published matrices are rounded (typically 6–10 decimals); derived values must
    // agree to that rounding.
    let f = fixtures();
    for (key, m) in f["published_npm"].as_object().unwrap() {
        let ours = gamut_for(key).rgb_to_xyz();
        let d = (ours - mat(m)).abs().max();
        assert!(d < 1e-5, "{key}: derived NPM differs from published by {d}");
    }
}

#[test]
fn dwg_matches_blackmagic_document() {
    let f = fixtures();
    let d1 = (davinci::dwg_to_xyz() - mat(&f["dwg_doc"]["rgb_to_xyz"])).abs().max();
    let d2 = (davinci::xyz_to_dwg() - mat(&f["dwg_doc"]["xyz_to_rgb"])).abs().max();
    // The document prints 8 decimals.
    assert!(d1 < 6e-9, "DWG→XYZ off by {d1}");
    assert!(d2 < 6e-9, "XYZ→DWG off by {d2}");
}

#[test]
fn dwg_xyz_round_trip() {
    let m = davinci::xyz_to_dwg() * davinci::dwg_to_xyz();
    assert!((m - Mat3::identity()).abs().max() < 1e-14);
    // and in float32, as the DCTL will run it
    let a = davinci::dwg_to_xyz().map(|v| v as f32);
    let b = davinci::xyz_to_dwg().map(|v| v as f32);
    for rgb in [[0.18f32, 0.18, 0.18], [1.0, 0.0, 0.0], [0.02, 0.4, 1.7], [8.0, 3.0, 0.5]] {
        let v = nalgebra::Vector3::from(rgb);
        let back = b * (a * v);
        assert!((back - v).abs().max() < 1e-5 * v.abs().max().max(1.0));
    }
}

#[test]
fn chromatic_adaptation_matches_colour_science() {
    let f = fixtures();
    let cases = [
        ("bradford_aces_to_d65", Cat::Bradford, whites::ACES),
        ("cat02_aces_to_d65", Cat::Cat02, whites::ACES),
        ("bradford_dci_to_d65", Cat::Bradford, whites::DCI),
    ];
    for (key, cat, src) in cases {
        let d = (cat.matrix(src, whites::D65) - mat(&f["cat"][key])).abs().max();
        assert!(d < 1e-12, "{key} differs by {d}");
    }
}

#[test]
fn pq_matches_colour_science_and_round_trips() {
    let f = fixtures();
    for row in f["pq"].as_array().unwrap() {
        let nits = row[0].as_f64().unwrap();
        let want = row[1].as_f64().unwrap();
        assert!((pq_inverse_eotf(nits) - want).abs() < 1e-12, "PQ({nits})");
        assert!((pq_eotf(want) - nits).abs() <= 1e-9 * nits.max(1.0), "PQ⁻¹({want})");
    }
}

#[test]
fn pq_round_trip_at_preset_peaks() {
    use lutmatrix_core::spaces::display::PQ_PEAK_PRESETS;
    use lutmatrix_core::spaces::{DisplayGamut, DisplayTransfer, OutputSpace};
    for peak in PQ_PEAK_PRESETS {
        let o = OutputSpace::new(DisplayGamut::Rec2020, DisplayTransfer::Pq { peak_nits: peak });
        for i in 0..=100 {
            let nits = peak * i as f64 / 100.0;
            let back = o.decode_channel(o.encode_channel(nits));
            assert!((back - nits).abs() <= 1e-9 * nits.max(1.0), "peak {peak}: {nits} → {back}");
        }
        assert!(o.encode_channel(peak) <= 1.0);
    }
}

#[test]
fn gamma_round_trip() {
    use lutmatrix_core::spaces::{DisplayGamut, DisplayTransfer, OutputSpace};
    for g in [2.2, 2.4, 2.6] {
        let o = OutputSpace::new(DisplayGamut::Rec709, DisplayTransfer::Gamma { gamma: g });
        for i in 0..=100 {
            let v = i as f64 / 100.0;
            assert!((o.encode_channel(o.decode_channel(v)) - v).abs() < 1e-12);
        }
    }
}

#[test]
fn white_points_map_to_neutral() {
    // RGB (1,1,1) in each gamut lands on its stated white chromaticity.
    for p in [gamuts::P3_DCI, gamuts::AP1, gamuts::AP0, gamuts::BMD_WG_GEN5, gamuts::DWG] {
        let xyz = p.rgb_to_xyz() * Vec3::new(1.0, 1.0, 1.0);
        let xy = lutmatrix_core::math::Xy::from_xyz(&xyz);
        assert!((xy.x - p.white.x).abs() < 1e-14 && (xy.y - p.white.y).abs() < 1e-14);
    }
}

#[test]
fn delta_e_2000_matches_colour_science() {
    use lutmatrix_core::difference::{delta_e_2000, xyz_to_lab};
    let f = fixtures();
    for c in f["delta_e_2000"].as_array().unwrap() {
        let v = |k: &str| Vec3::from(<[f64; 3]>::try_from(serde_json::from_value::<Vec<f64>>(c[k].clone()).unwrap()).unwrap());
        let w = v("white");
        let la = xyz_to_lab(&v("xyz1"), &w);
        assert!((la - v("lab1")).abs().max() < 1e-9, "Lab");
        let d = delta_e_2000(&la, &xyz_to_lab(&v("xyz2"), &w));
        let want = c["de2000"].as_f64().unwrap();
        assert!((d - want).abs() < 1e-9, "ΔE2000 {d} vs {want}");
    }
}

#[test]
fn delta_e_itp_matches_colour_science() {
    use lutmatrix_core::difference::{delta_e_itp, xyz_nits_to_ictcp};
    let f = fixtures();
    for c in f["delta_e_itp"].as_array().unwrap() {
        let v = |k: &str| Vec3::from(<[f64; 3]>::try_from(serde_json::from_value::<Vec<f64>>(c[k].clone()).unwrap()).unwrap());
        let ia = xyz_nits_to_ictcp(&v("xyz1"));
        assert!((ia - v("ictcp1")).abs().max() < 1e-9, "ICtCp {ia:?}");
        let d = delta_e_itp(&ia, &xyz_nits_to_ictcp(&v("xyz2")));
        let want = c["de_itp"].as_f64().unwrap();
        assert!((d - want).abs() < 1e-7 * want.max(1.0), "ΔE ITP {d} vs {want}");
    }
}
